-- 1. CREATE TABLE IF NOT EXISTS
CREATE TABLE IF NOT EXISTS public.job_postings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    job_title TEXT NOT NULL,
    company_name TEXT,
    location TEXT,
    apply_url TEXT NOT NULL,
    match_score TEXT,
    relevance TEXT,
    posted_at TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 2. ENABLE RLS AND POLICIES
ALTER TABLE public.job_postings ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = 'job_postings' AND policyname = 'Allow public read and insert on job_postings'
    ) THEN
        CREATE POLICY "Allow public read and insert on job_postings" ON public.job_postings
        FOR ALL USING (true) WITH CHECK (true);
    END IF;
END $$;

